"""Build the approved homepage from public guide and product metadata."""
import json,re
from pathlib import Path
from html import escape as e
from decimal import Decimal
from toolkit_catalog import load_catalog,product_route
R=Path(__file__).resolve().parents[1]
guides=[json.loads(p.read_text()) for p in (R/'content/guides').glob('*.json')]
categories=json.loads((R/'content/taxonomy.json').read_text())
catalog=load_catalog(R);topics=[p for p in catalog['products'] if p['kind']=='topic' and p['status']!='retired']
benefits={'power-outage':'Plan lighting, protect food and organize your household through a blackout.','water-disruption':'Organize safe water reserves, understand notices and plan household hygiene.','emergency-food':'Build a usable pantry with no-cook meals, shopping lists and a rotation plan.','evacuation':'Choose destinations, prepare carryable bags and coordinate transport and check-ins.'}
cards=''
for p in topics:
 ready=p['status']=='ready';complete=p['status']=='files-ready'
 status='Available now' if ready else 'Checkout opening soon' if complete else 'Redesign underway · Purchases paused'
 price=f' · ${Decimal(str(p["price"])):.2f}' if ready else ''
 image=f'<div class="home-kit-preview"><img src="/Assets/toolkit-previews/{p["slug"]}.webp" alt="Previous edition cover of the {e(p["title"])} guide" width="602" height="850" loading="lazy" decoding="async"><span>PREVIOUS EDITION PREVIEW</span></div>' if (R/f'Assets/toolkit-previews/{p["slug"]}.webp').is_file() else ''
 link=('<a class="button button-primary" data-payhip-checkout href="'+e(p['checkout_url'],quote=True)+'">Buy toolkit'+price+'</a>') if ready else f'<a class="text-link" href="{product_route(p)}">View toolkit <span aria-hidden="true">→</span></a>'
 cards+=f'<article class="home-kit-card">{image}<div class="home-kit-copy"><p class="home-kit-status">{status}</p><h3><a href="{product_route(p)}">{e(p["title"])}</a></h3><p>{e(benefits.get(p["slug"],p["summary"]))}</p>{link}</div></article>'
subjects=''.join(f'<a href="/library/{c["id"]}/"><span>{e(c["title"])}</span><small>{sum(g["category"]==c["id"] for g in guides)} {"guide" if sum(g["category"]==c["id"] for g in guides)==1 else "guides"} <span aria-hidden="true">↗</span></small></a>' for c in categories)
quick=[('Power outage','/emergencies/power-outage/','Lighting, food and safe backup power'),('Unsafe water','/emergencies/water-disruption/','Read the notice and choose safe water'),('Severe weather','/emergencies/severe-weather/','Choose the specific hazard'),('Evacuation','/emergencies/evacuation/','Leave with a destination and a plan'),('Home fire','/emergencies/home-fire/','Get out and stay out'),('First aid','/library/medical/','Find the response for the situation')]
featured_specs=[
 ('power-outage','UTILITIES','Power <br>outage.','When the lights go out.','<path d="m28 4-18 23h13l-3 17 18-24H25z"/>'),
 ('water-disruption','WATER','Water <br>disruption.','Start with the right water notice.','<path d="M24 5C18 14 10 23 10 31a14 14 0 0 0 28 0C38 23 30 14 24 5Z"/><path d="M17 32a7 7 0 0 0 7 7"/>'),
 ('hurricane','WEATHER','Hurricane.','Know your zone. Know your next move.','<path d="M8 21h24a7 7 0 1 0-7-7M5 28h30a6 6 0 1 1-6 6M12 35h9"/>'),
 ('home-fire','HOME SAFETY','Home <br>fire.','Get out. Stay out.','<path d="M24 4c3 11 13 15 13 26a13 13 0 0 1-26 0c0-7 4-12 7-16 0 8 3 10 5 11 4-6 4-13 1-21Z"/>'),
 ('severe-bleeding','FIRST AID','Severe <br>bleeding.','Find the first protective actions.','<path d="M18 6h12v12h12v12H30v12H18V30H6V18h12Z"/>')
]
book_pages=''
book_dots=''
book_fallback=''
for n,(slug,topic,title,deck,icon) in enumerate(featured_specs):
 g=next(g for g in guides if g['slug']==slug)
 steps=''.join(f'<li><span>0{i+1}</span><div><h3>{e(step[0])}</h3><p>{e(step[1])}</p></div></li>' for i,step in enumerate(g['steps'][:2]))
 state=' class="field-sheet is-current"' if n==0 else ' class="field-sheet" hidden inert aria-hidden="true"'
 book_pages+=f'<article{state} data-book-page data-title="{e(g["title"],quote=True)}" id="field-page-{n+1}" role="group" aria-roledescription="slide" aria-label="{n+1} of {len(featured_specs)}: {e(g["title"],quote=True)}"><div class="field-sheet-top"><span>GUIDE PREVIEW</span><span>{n+1:02d} / {len(featured_specs):02d} · {topic}</span></div><div class="field-sheet-brand"><img src="/Assets/oz-mark.webp" alt="" width="46" height="46"><span>THE OSPREY ZERO<br>FIELD MANUAL</span><svg width="44" height="44" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">{icon}</svg></div><h2>{title}</h2><p class="field-sheet-deck">{deck}</p><div class="field-answer-label"><span>FIRST CHECKS</span><span>READ. THEN ACT.</span></div><ol class="field-preview-steps">{steps}</ol><a class="field-read-link" href="/emergencies/{slug}/">Open {e(g["title"])} guide <span aria-hidden="true">↗</span></a><p class="field-preview-note">Excerpt only. Read the full actions, exceptions and sources.</p></article>'
 book_dots+=f'<button type="button" data-book-go="{n}" aria-label="Show {e(g["title"],quote=True)} preview" aria-controls="field-page-{n+1}"'+(' aria-current="true"' if n==0 else '')+f'><span aria-hidden="true">{n+1:02d}</span></button>'
 book_fallback+=f'<a href="/emergencies/{slug}/">{e(g["title"])}</a>'
quicklinks=''.join(f'<a class="home-situation" href="{url}"><strong>{e(title)}</strong><span>{e(desc)}</span><b aria-hidden="true">↗</b></a>' for title,url,desc in quick)
main=f'''<main id="main" class="home-page">
<section class="wrap home-hero field-hero" aria-labelledby="hero-title">
<div class="home-hero-stage"><div class="home-hero-intro"><p class="kicker"><span class="accent-line" aria-hidden="true"></span> CIVILIAN KNOWLEDGE. FREE ACCESS.</p><h1 id="hero-title"><span>SKILL </span><span>BEATS </span><span class="hero-panic">PANIC.</span></h1><p class="hero-everytime">Every time.</p><p class="home-lede">Clear answers when it matters.<br>Practical skills before it does.</p><div class="home-hero-actions"><a class="button button-primary" href="/emergencies/">Find emergency guidance <span aria-hidden="true">↗</span></a><a class="hero-secondary" href="/library/">Explore all topics <span aria-hidden="true">→</span></a></div><div class="finder-bar home-finder"><label for="emergency-search">Search {len(guides)} free guides</label><div class="search-control"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="emergency-search" type="search" placeholder="What do you need to know?" autocomplete="off" aria-controls="home-search-results"></div><span class="finder-count" id="finder-count" role="status" aria-live="polite" aria-atomic="true">No account. No signup. Just useful knowledge.</span></div><div id="home-search-results" class="search-results" hidden></div></div>
<aside class="field-preview field-book" data-field-book role="region" aria-roledescription="carousel" aria-label="Featured guide previews" tabindex="0"><div class="field-spine" aria-hidden="true">OSPREY ZERO / FIELD KNOWLEDGE</div><div class="field-book-stack">{book_pages}</div><div class="field-book-controls" data-book-controls hidden><div class="book-control-row"><button type="button" class="book-arrow" data-book-prev aria-label="Previous guide preview"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg></button><div class="book-page-label"><span>TURN THE PAGE</span><strong data-book-count>1 / 5 · Power outage</strong></div><button type="button" class="book-arrow" data-book-next aria-label="Next guide preview"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m10 6 6 6-6 6M16 12H4"/></svg></button></div><div class="book-page-dots" aria-label="Choose a guide preview">{book_dots}</div></div><p class="field-book-help" id="field-book-help" data-book-hint hidden>Swipe left or right, or use the page controls. Arrow keys work when this preview has focus.</p><p class="book-live-status" data-book-status role="status" aria-live="polite" aria-atomic="true"></p><noscript><div class="book-fallback"><p>Explore these free guides</p>{book_fallback}</div></noscript><div class="field-preview-caption"><span>{len(guides)} FREE GUIDES</span><span>{len(categories)} SUBJECTS</span><span>BUILT FOR REAL LIFE</span></div></aside></div>
<div class="hero-urgent" aria-label="Urgent situations"><span>Need a first step now?</span><a href="/emergencies/cpr/">Not breathing</a><a href="/emergencies/choking/">Choking</a><a href="/emergencies/gas-leak/">Smell gas</a><a href="/emergencies/home-fire/">Fire</a></div><noscript><p>Search needs JavaScript. <a href="/library/">Browse all free guides</a>.</p></noscript></section>
<section class="wrap home-common" id="find-help" aria-labelledby="common-title"><div class="home-section-heading"><div><p class="kicker">01 / FIND YOUR NEXT STEP</p><h2 id="common-title">Start with what’s happening.</h2></div><a class="text-link" href="/emergencies/">All emergency guides →</a></div><div class="topic-grid home-situation-grid" id="topic-grid">{quicklinks}</div><p class="home-safety-note">Act on immediate danger. Seek qualified help when reachable and safe; do not wait for a response to take the first protective step.</p></section>
<section class="wrap home-encyclopedia" aria-labelledby="encyclopedia-title"><div class="home-section-heading"><div><p class="kicker">02 / {len(categories)} SUBJECTS. ONE FIELD MANUAL.</p><h2 id="encyclopedia-title">Explore what matters to you.</h2></div><a class="text-link" href="/topics/">Every topic A–Z →</a></div><div class="home-subject-grid">{subjects}</div><div class="home-trust-strip"><span>Quick answers</span><span>Practical steps</span><span>Linked sources</span><a href="/resources/">Explore the references ↗</a></div></section>
<section class="home-start-band"><div class="wrap home-start" aria-labelledby="start-title"><div class="home-section-heading"><div><p class="kicker">03 / START PREPARING</p><h2 id="start-title">Start small. Build confidence.</h2></div><p>You don’t need to buy everything at once. Begin with your people, your essentials and a plan you can actually use.</p></div><ol class="home-start-grid"><li><span>STEP 1</span><h3>Make your household plan.</h3><p>Choose contacts, meeting points and what would make you stay or leave.</p><a class="text-link" href="/preparedness/household-emergency-plan/">Build your plan →</a></li><li><span>STEP 2</span><h3>Secure the essentials.</h3><p>Prioritize water, food, lighting and care needs around your budget.</p><a class="text-link" href="/preparedness/budget-preparedness/">Prepare on a budget →</a></li><li><span>STEP 3</span><h3>Practice and maintain.</h3><p>Test the plan, check your supplies and fix one useful gap at a time.</p><a class="text-link" href="/preparedness/preparedness-maintenance/">Keep it ready →</a></li></ol></div></section>
<section class="wrap home-toolkits" id="guide-access" aria-labelledby="access-title"><div class="home-section-heading"><div><p class="kicker">04 / PREPARATION TOOLKITS</p><h2 id="access-title">Turn knowledge<br><span>into a plan you can use.</span></h2></div><p>Our toolkits are being redesigned with more practical guides, checklists and household tools. Purchases are paused while we prepare the new editions.</p></div><div class="home-kit-grid">{cards}</div><div class="home-kit-footer"><p>Free guidance stays free. Toolkits bring the printable resources and planning tools together.</p><a class="text-link" href="/toolkits/">Explore all toolkits →</a></div></section>
<section class="wrap home-planner" aria-labelledby="planner-title"><div><p class="kicker">HOUSEHOLD PLANNER / SEPARATE PRODUCT</p><h2 id="planner-title">Your household.<br><span>One clear plan.</span></h2><p>Manage supplies, contacts, budgets and tasks in one practical dashboard. Spot gaps, plan your next purchase and keep your household information organized.</p><div class="home-planner-actions"><a class="button button-outline" href="/planner/">Explore the planner →</a><a class="text-link" href="/planner/app/">Already own it? Open the app ↗</a></div><p class="home-planner-note">Separate from the toolkits. Customers import their purchased app file; records stay in their browser. No account or cloud sync. New purchases open after checkout is verified.</p></div><div class="home-planner-features" aria-label="Planner features"><div><span>SUPPLIES</span><h3>Know what you have.</h3><p>Water, food, inventory and shopping priorities.</p></div><div><span>PEOPLE</span><h3>Keep the plan together.</h3><p>Contacts, household needs and printable plans.</p></div><div><span>UPKEEP</span><h3>See what needs attention.</h3><p>Budgets, tasks, maintenance and editable backups.</p></div></div></section>
<section class="home-mission-band"><div class="wrap home-mission"><div><p class="kicker">OUR MISSION</p><h2>Preparedness within reach.</h2><p>Osprey Zero was founded by Michael LaChance in Florida to put useful knowledge, resources and tools in the hands of everyday people—before they need them. Our encyclopedia is free to read, and our toolkits help turn that knowledge into practical household preparation.</p><a class="text-link" href="/about/">Meet Osprey Zero →</a></div><div class="home-update" id="newsletter"><p class="kicker">FIELD NOTES</p><h3>Follow what’s next.</h3><p>Request updates about new guides and toolkit releases. Email delivery is being set up; free guides never require signup.</p><form data-signup="field-notes-newsletter" name="field-notes-newsletter" method="POST" data-netlify="true" netlify-honeypot="bot-field" action="/thanks/"><input type="hidden" name="form-name" value="field-notes-newsletter"><p class="honeypot"><label>Leave this empty <input name="bot-field"></label></p><label for="newsletter-email">Email address</label><div class="email-row"><input id="newsletter-email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required><button class="button button-ash" type="submit">Request updates →</button></div><p class="form-note"><a href="/privacy/">Privacy & email details</a></p><p class="form-status" data-form-status role="status" aria-live="polite"></p></form></div></div></section>
<section class="wrap home-clipjar"><div><p class="kicker">AN OSPREY ZERO PROJECT</p><h2>Keep our videos close.</h2><p>Use ClipJar to save Osprey Zero videos you have permission to keep for offline viewing.</p></div><a class="button button-outline" href="https://clipjar.io/" target="_blank" rel="noopener noreferrer">Open ClipJar ↗</a></section>
</main>'''
p=R/'index.html';s=p.read_text();s=re.sub(r'<main id="main".*?</main>',lambda _:main,s,flags=re.S)
s=re.sub(r'<meta name="description"[^>]*>','<meta name="description" content="Search free emergency and preparedness guides. Explore Osprey Zero toolkits, household planning tools, checklists and practical resources.">',s)
s=re.sub(r'<script src="/field-book.js[^"]*"[^>]*></script>', '', s)
s=s.replace('</head>','<script src="/field-book.js?v=book1" defer></script></head>')
p.write_text(s)
print(f'Built streamlined homepage: {len(guides)} guides, {len(topics)} topic toolkits, one search.')
